-- EN reconciliation for the 5 milestones where D1 had drifted from the
-- tracker ("tracker phrasing wins" -- the standing rule -- with each
-- fact verified this session): eu-transpose (em-dash restored from a
-- '--' escaping artifact), pt-b2g-sme + pt-qes (deep-dive phrasing
-- replaced with tracker phrasing; pt-qes gains the tracker's extra
-- closing sentence), mx-cfdi (2014-01-01: CFDI's legal mandate date,
-- April was only the end of small-taxpayer transition relief), and
-- cl-established (2018-01-01: matches the milestone's own 'in force
-- since 2018' claim -- Chile's Law 20.727 phase-in completed Feb 2018;
-- D1's 2014 was the law's start, contradicting the entry text).

UPDATE milestones SET date = '2014-01-01' WHERE id = 'mx-cfdi';
UPDATE milestones SET date = '2018-01-01' WHERE id = 'cl-established';
UPDATE milestone_translations SET system = 'ViDA — Single VAT Registration transposition deadline', desc = 'Member states must transpose the Single VAT Registration (SVR) provisions of the ViDA Directive into national law by this date, so the expanded One Stop Shop (OSS)/Import One Stop Shop (IOSS) scope and related clarifications can apply from 1 January 2027. This deadline is specific to the SVR pillar — it is separate from, and earlier than, the transposition timelines for ViDA''s platform-economy pillar (2028) and its e-invoicing/Digital Reporting Requirements pillar (2030).', actions = '["If you sell cross-border B2C goods or services within the EU, confirm your OSS/IOSS registration covers the expanded scope taking effect January 2027","This deadline does not itself require domestic e-invoicing — member states can already introduce their own e-invoicing mandates independently, under derogations available since ViDA''s April 2025 entry into force","Track your national tax authority''s own transposition and domestic e-invoicing timeline separately from this EU-wide SVR deadline"]' WHERE milestone_id = 'eu-transpose' AND lang = 'en';
UPDATE milestone_translations SET system = 'B2G mandate extends to small, medium, and micro-enterprises', desc = 'The CIUS-PT structured e-invoicing requirement for public-sector suppliers, previously applying only to large companies, now extends to small, medium, and micro-enterprises. Separately, regardless of company size or whether B2G applies, all invoices — paper or electronic — must already be issued using AT-certified software and carry an ATCUD code, a QR code, and a hash chain for authenticity.', actions = '["If you supply any Portuguese public-sector body and don''t yet issue structured CIUS-PT invoices, this is now a live compliance gap, not a future one","Independently of B2G status, confirm your invoicing software is on the AT-certified list — using uncertified software makes an invoice invalid regardless of its content"]' WHERE milestone_id = 'pt-b2g-sme' AND lang = 'en';
UPDATE milestone_translations SET system = 'Qualified Electronic Signature (QES) required for PDF invoices', desc = 'PDF invoices in B2B and B2C transactions will require a Qualified Electronic Signature from an EU-listed trust service provider to remain legally valid — deferred from an original 2026 date via the 2026 State Budget. Until 31 December 2026, PDF invoices issued by certified software with ATCUD and a QR code remain valid without a QES. This layer applies on top of, not instead of, the certified-software/ATCUD/QR/SAF-T requirements already in force.', actions = '["Identify an EU-listed qualified trust service provider for QES well before the 2027 deadline — this is a distinct procurement step, not a software setting","Don''t assume compliance with the existing ATCUD/QR/certified-software requirements covers this — QES is a genuinely new, additional layer specifically for PDF invoices"]' WHERE milestone_id = 'pt-qes' AND lang = 'en';
